using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;
using ResearchAgent;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to your OpenAI API key.");

const string modelId = "gpt-4o-mini-2024-07-18";

// --- Build the chat client via MEAI abstraction ---
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Define tools ---
var tools = new ResearchTools();
var aiTools = new List<AITool>
{
    AIFunctionFactory.Create(tools.SearchWeb),
    AIFunctionFactory.Create(tools.SaveNote),
    AIFunctionFactory.Create(tools.GetNotes),
};

// --- Create the research agent ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Your job is to thoroughly research a topic provided by the user.

        Follow this workflow:
        1. Search the web with multiple varied queries to gather broad information.
        2. Save important findings as notes using the SaveNote tool.
        3. After gathering enough information, retrieve your notes with GetNotes.
        4. Provide a comprehensive summary of your findings organized with clear headings.

        Be thorough — use at least 2-3 different search queries to cover different angles.
        Always cite your sources by including URLs.
        """,
    name: "ResearchAgent",
    description: "Researches topics by searching the web and summarizing findings",
    tools: aiTools);

// --- Run the agent ---
Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");
Console.WriteLine("Working...\n");

var response = await agent.RunAsync(
    $"Please research the following topic and provide a comprehensive summary: {topic}");

Console.WriteLine(response.Text);

